<script setup lang="ts">
import { ref } from "vue";
import { ElMessage, ElMessageBox } from "element-plus";
import StoryPlayer from "~/components/account/version-summary/StoryPlayer.vue";
import { normalizeAnnualSummary } from "~/utils/annualSummary";
defineI18nRoute(false); definePageMeta({ layout: "admin-taiko", middleware: "admin-auth" }); useHead({ title: "年度报告" });
const apiFetch = useAdminApiFetch(); const query = ref(""); const loading = ref(false); const items = ref<any[]>([]); const preview = ref<any>(null); const previewStarted = ref(false); const actionId = ref(""); const { t } = useI18n();
const previewSummary = computed(() => preview.value ? normalizeAnnualSummary(preview.value, "zh", (key, params) => t(key, params || {})) : null);
const search = async () => { loading.value = true; try { items.value = (await apiFetch<{ items: any[] }>("/api/admin/annual-summaries", { query: { q: query.value } })).items; } catch (e:any) { ElMessage.error(e?.data?.statusMessage || "查询失败"); } finally { loading.value = false; } };
const openSummary = (summaryId:string) => { if (summaryId) return navigateTo(`/admin/taiko/annual-summaries/${encodeURIComponent(summaryId)}`); };
const waitForBuild = async (jobId:string) => { const deadline = Date.now() + 4 * 60 * 1000; while (Date.now() < deadline) { const result = await apiFetch<{job:any; summary?:any}>(`/api/admin/annual-summary-jobs/${encodeURIComponent(jobId)}`, { query: { locale: "zh" } }); if (result.job.status === "completed") { if (result.summary?.summaryId || result.job.summaryId) return result.summary?.summaryId || result.job.summaryId; throw new Error("年度报告文件不可用"); } if (result.job.status === "failed") throw new Error(result.job.error?.message || "生成失败"); await new Promise(resolve => window.setTimeout(resolve, 1200)); } throw new Error("生成超时，请稍后重试"); };
const build = async (item:any, force=false) => { if (actionId.value) return; if (item.hasViewerAccount && item.summaryId && !force) return openSummary(item.summaryId); actionId.value = `${item.taikoId}:${force ? "force" : "build"}`; try { if (item.hasViewerAccount) { const result = await apiFetch<{job:any; summary?:any}>("/api/admin/annual-summaries/build", { method: "POST", body: { userId: item.userId, bindingId: item.bindingId, force } }); const summaryId = result.summary?.summaryId || result.job?.summaryId || await waitForBuild(result.job.id); if (summaryId) await openSummary(summaryId); } else { const result = await apiFetch<{summary:any}>("/api/admin/annual-summaries/build", { method: "POST", body: { taikoId: item.taikoId } }); preview.value = result.summary; previewStarted.value = false; } } catch (e:any) { ElMessage.error(e?.data?.statusMessage || e?.message || "生成失败"); } finally { actionId.value = ""; } };
const remove = async (item:any) => { if (!item.summaryId || actionId.value) return; try { await ElMessageBox.confirm("删除后需要重新生成年度报告，确定继续吗？", "删除年度缓存", { type: "warning", confirmButtonText: "删除", cancelButtonText: "取消" }); actionId.value = `delete:${item.summaryId}`; await apiFetch(`/api/admin/annual-summaries/${encodeURIComponent(item.summaryId)}`, { method: "DELETE" }); ElMessage.success("年度缓存已删除"); await search(); } catch (e:any) { if (e !== "cancel" && e !== "close") ElMessage.error(e?.data?.statusMessage || "删除失败"); } finally { actionId.value = ""; } };
</script>
<template><div class="admin-page-stack"><div class="page-heading"><div><span class="eyebrow">Annual reports</span><h2>年度报告管理</h2><p>扫描全部 userdata，按鼓众 ID、真实昵称或用户名模糊匹配；无 Viewer 账号的数据也可生成预览。</p></div></div><el-card><div class="search"><el-input v-model="query" placeholder="输入鼓众 ID、昵称或用户名" clearable @keyup.enter="search" /><el-button type="primary" :loading="loading" @click="search">查询</el-button></div><el-table v-if="items.length" :data="items" stripe><el-table-column prop="nickname" label="昵称"/><el-table-column prop="username" label="用户名"/><el-table-column prop="taikoId" label="鼓众 ID"/><el-table-column label="状态"><template #default="{row}"><span v-if="row.summaryId" class="status-ready">已生成</span><span v-else>{{ row.hasViewerAccount ? '待生成' : '仅预览' }}</span></template></el-table-column><el-table-column label="操作" width="320"><template #default="{ row }"><el-button link type="primary" :loading="actionId === `${row.taikoId}:build`" @click="build(row)">{{ row.summaryId ? '查看报告' : row.hasViewerAccount ? '生成报告' : '生成预览' }}</el-button><el-button v-if="row.hasViewerAccount" link type="warning" :loading="actionId === `${row.taikoId}:force`" @click="build(row,true)">强制重建</el-button><el-button v-if="row.summaryId" link type="danger" :loading="actionId === `delete:${row.summaryId}`" @click="remove(row)">删除缓存</el-button></template></el-table-column></el-table><el-empty v-else description="暂无结果" /></el-card><div v-if="previewSummary" class="preview"><button class="preview__close" @click="preview=null">关闭预览</button><StoryPlayer :summary="previewSummary" :started="previewStarted" @start="previewStarted=true" @open-drawer="preview=null" /></div></div></template>
<style scoped>.admin-page-stack{display:grid;gap:20px}.page-heading h2{margin:6px 0;font-size:30px}.page-heading p{margin:0;color:#6b7280}.eyebrow{color:#8f6d3f;font-size:12px;letter-spacing:.14em;text-transform:uppercase}.search{display:flex;gap:10px;margin-bottom:18px}.search .el-input{max-width:420px}.status-ready{color:#257a4b;font-weight:600}</style>
